     align-items: center;
     margin-top: 1rem;
 }

 .hero-button {
     min-width: 180px;
 }

 .hero-spotlight {
     position: relative;
 }

 .hero-spotlight-card {
     background: rgba(15, 23, 42, 0.6);
     border-radius: var(--radius-xl);
     padding: 1.5rem;
     border: 1px solid rgba(255, 255, 255, 0.25);
     display: flex;
     flex-direction: column;
     gap: 0.25rem;
     min-height: 180px;
 }

 .hero-spotlight-label {
     margin: 0;
     font-size: 0.75rem;
     text-transform: uppercase;
     letter-spacing: 0.16em;
     color: var(--surface-2);
 }

 .hero-spotlight-card h2 {
     margin: 0;
     font-size: 2rem;
     line-height: 1.2;
 }

 .hero-spotlight-subtitle {
     margin: 0;
     color: var(--surface-2);
     font-size: 0.9rem;
 }

 .stats-section,
 .summary-section,
 .panel-section {
     background: var(--surface);
     border-radius: var(--radius-xl);
     padding: clamp(1.5rem, 2vw, 2.5rem);
     box-shadow: var(--shadow-2);
 }

 .section-heading {
     display: flex;
     justify-content: space-between;
     gap: 1rem;
     align-items: flex-end;
     margin-bottom: 1.25rem;
     flex-wrap: wrap;
 }

 .section-eyebrow {
     margin: 0;
     letter-spacing: 0.2em;
     text-transform: uppercase;
     font-size: 0.7rem;
     color: var(--text-secondary);
 }

 .section-title {
     margin: 0;
     font-size: clamp(1.4rem, 2vw, 2rem);
 }

 .section-note {
     margin: 0;
     font-size: 0.9rem;
     color: var(--text-secondary);
     max-width: 36rem;
 }

 .stats-grid {
     display: grid;
     grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
     gap: 1rem;
 }

 .stat-card {
     border-radius: var(--radius-lg);
     border: 1px solid var(--border);
     padding: 1.25rem;
     background: var(--surface-2);
     display: flex;
     flex-direction: column;
     gap: 0.5rem;
     min-height: 140px;
 }

 .stat-card-head {
     display: flex;
     justify-content: space-between;
     align-items: center;
 }

 .stat-label {
     font-size: 0.8rem;
     letter-spacing: 0.08em;
     text-transform: uppercase;
     color: var(--text-secondary);
 }

 .stat-value {
     font-size: 2rem;
     font-weight: 700;
     margin: 0;
 }

 .stat-amount {
     margin: 0;
     color: var(--text-secondary);
     font-size: 0.9rem;
 }

 .stat-chip {
     text-transform: none;
     font-weight: 600;
 }

 .loading-spinner {
     margin-right: 0.75rem;
 }

 .status-loading,
 .table-loading {
     display: inline-flex;
     gap: 0.5rem;
     align-items: center;
     color: var(--text-secondary);
 }

 .status-error {
     margin: 0;
 }

 .summary-section {
     display: flex;
     flex-direction: column;
     gap: 1rem;
 }

 .merchant-table {
     border-radius: var(--radius-lg);
     border: 1px solid var(--border);
     overflow: hidden;
 }

 .merchant-cell {
     display: flex;
     flex-direction: column;
     gap: 0.25rem;
 }

 .merchant-id {
     color: var(--text-secondary);
     font-size: 0.75rem;
 }

 .table-error,
 .table-empty {
     padding: 1.25rem;
     border-radius: var(--radius-lg);
     border: 1px dashed var(--border);
     color: var(--text-secondary);
 }

 .align-right {
     text-align: right;
 }

 .panel-section {
     display: grid;
     grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
     gap: 1rem;
 }

 .panel {
     display: flex;
     flex-direction: column;
     gap: 1rem;
     background: var(--surface);
 }

 .panel-heading {
     display: flex;
     flex-direction: column;
     gap: 0.35rem;
 }

 .panel-grid {
     display: grid;
     grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
     gap: 1rem;
 }

 .infrastructure-item {
     border-radius: var(--radius-lg);
     border: 1px solid var(--border);
     padding: 1rem;
     background: var(--surface-3);
     display: flex;
     flex-direction: column;
     gap: 0.5rem;
 }

 .item-head {
     display: flex;
     justify-content: space-between;
     gap: 0.75rem;
     align-items: center;
 }

 .infrastructure-item h4 {
     margin: 0;
     font-size: 1rem;
 }

 .item-footnote {
     margin: 0;
     color: var(--text-secondary);
     font-size: 0.8rem;
 }

 .audit-list {
     margin: 0;
     padding-left: 1rem;
     display: flex;
     flex-direction: column;
     gap: 0.7rem;
     font-size: 0.95rem;
     color: var(--text-secondary);
 }

 @media (max-width: 768px) {
     .hero,
     .stats-section,
     .summary-section,
     .panel-section {
         padding: 1.5rem;
     }

     .hero-actions {
         justify-content: flex-start;
     }

     .hero-band {
         grid-template-columns: 1fr;
     }
 }

